import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"蒙","description":"周易正义 - 蒙","frontmatter":{"title":"蒙","description":"周易正义 - 蒙"},"headers":[],"relativePath":"zh/classics/zhengyi/004.md","filePath":"zh/classics/zhengyi/004.md"}'),l={name:"zh/classics/zhengyi/004.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>山水蒙</p></blockquote><blockquote><p>卦辞：亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。</p></blockquote><blockquote><p>彖曰：山下有险，险而止，蒙。蒙亨，以亨行时中也。匪我求童蒙，童蒙求我，志应也。初筮告，以刚中也。再三渎，渎则不告，渎蒙也。蒙以养正，圣功也。</p></blockquote><h1 id="蒙" tabindex="-1">蒙 <a class="header-anchor" href="#蒙" aria-label="Permalink to “蒙”">​</a></h1><p>王弼：“筮”，筮者决疑之物也。童蒙之来求我，欲决所惑也。决之不一，不知所从，则复惑也。故初筮则告，再、三则渎。渎，蒙也。能为初筮，其唯二乎？以刚处中，能断夫疑者也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“蒙亨”至“渎则不告”。○正义曰：蒙者，微昧闇弱之名。物皆蒙昧，唯原亨通，故云“蒙、亨”。“匪我求童蒙，童蒙求我”者，物既闇弱而意原亨通，即明者不求於闇，即匪我师德之高明往求童蒙之闇，但闇者求明，明者不谘於闇，故云“童蒙求我”也。“初筮告”者，初者，发始之辞；筮者，决疑之物。童蒙既来求我，我当以初始一理剖决告之。“再三渎，渎则不告”者，师若迟疑不定，或再或三，是亵渎，渎则不告。童蒙来问，本为决疑，师若以广深二义再三之言告之，则童蒙闻之，转亦渎乱，故不如不告也。自此以上，解“蒙亨”之义。顺此上事，乃得“亨”也。故“亨”文在此事之上也。不云“元”者，谓时当蒙弱，未有元也。○注“初筮告”。○正义曰：“初筮则告”者，童蒙既来求我，我当以初心所念所筮之义，一理而剖告之。“再三则渎，渎，蒙也”者，若以弃此初本之意，而犹豫迟疑，岐头别说，则童蒙之人，闻之亵渎而烦乱也。故“再三则渎，渎，蒙也”。“能为初筮，其唯二乎”者，以《彖》云“初筮告，以刚中”者，刚而得中故知是二也。</p><h3 id="利贞。-​" tabindex="-1">利贞。 ​ <a class="header-anchor" href="#利贞。-​" aria-label="Permalink to “利贞。 ​”">​</a></h3><p>王弼：“蒙”之所利，乃利正也。夫明莫若圣，昧莫若蒙。蒙以养正乃圣功也。然则养正以明，失其道矣。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“利贞”。○正义曰：贞，正也。言蒙之为义，利以养正，故《彖》云“蒙以养正”，乃“圣功也”。若养正以明，即失其道也。○注“然则养正以明失其道”。○正义曰：“然则养正以明，失其道”者，言人虽怀圣德，若隐默不言，人则莫测其浅深，不知其大小，所以圣德弥远而难测矣。若彰显其德，苟自发明，即人知其所为，识其浅深。故《明夷》注云“明夷莅众，显明於外，巧所避”是也。此卦，《系辞》皆以人事明之。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="蒙-山下有险-险而止-蒙。-​" tabindex="-1">蒙，山下有险，险而止，蒙。 ​ <a class="header-anchor" href="#蒙-山下有险-险而止-蒙。-​" aria-label="Permalink to “蒙，山下有险，险而止，蒙。 ​”">​</a></h3><p>王弼：退则困险，进则阂山，不知所適，蒙之义也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“山下有险”者，坎在艮下，是山下有险。艮为止，坎上遇止，是险而止也。恐进退不可，故蒙昧也。此释蒙卦之名。</p><h3 id="蒙-亨-以亨行-时中也。-​" tabindex="-1">“蒙，亨”，以亨行，时中也。 ​ <a class="header-anchor" href="#蒙-亨-以亨行-时中也。-​" aria-label="Permalink to ““蒙，亨”，以亨行，时中也。 ​”">​</a></h3><p>王弼：时之所愿，惟愿“亨”也。以亨行之，得“时中”也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：叠“蒙亨”之义，言居“蒙“之时，人皆愿“亨”。若以亨道行之于时，则得中也。故云“时中”也。</p><h3 id="匪我求童蒙-童蒙求我-志应也。-​" tabindex="-1">“匪我求童蒙，童蒙求我”，志应也。 ​ <a class="header-anchor" href="#匪我求童蒙-童蒙求我-志应也。-​" aria-label="Permalink to ““匪我求童蒙，童蒙求我”，志应也。 ​”">​</a></h3><p>王弼：“我”谓非“童蒙”者也。非“童蒙”者，即阳也。凡不识者求问识者，识者不求所告；闇者求明，明者不谘於闇。故《蒙》之为义，“匪我求童蒙，童蒙求我”也。童蒙之来求我，志应故也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以童蒙闇昧之志，而求应会明者，故云“志应”也。</p><h3 id="初筮告-以刚中也。-​" tabindex="-1">初筮告，以刚中也。 ​ <a class="header-anchor" href="#初筮告-以刚中也。-​" aria-label="Permalink to “初筮告，以刚中也。 ​”">​</a></h3><p>王弼：谓二也。二为众阴之主也，无刚失中，何由得初筮之告乎？</p><h3 id="再三渎-渎则不告。渎-蒙也。蒙以养正-圣功也。-​" tabindex="-1">再三渎，渎则不告。渎，蒙也。蒙以养正，圣功也。 ​ <a class="header-anchor" href="#再三渎-渎则不告。渎-蒙也。蒙以养正-圣功也。-​" aria-label="Permalink to “再三渎，渎则不告。渎，蒙也。蒙以养正，圣功也。 ​”">​</a></h3><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“再三渎，渎则不告。渎，蒙”者，所以再三不告，恐渎乱蒙者。自此以上，《彖》辞总释“蒙亨”之义。“蒙以养正，圣功也”者，能以蒙昧隐默自养正道，乃成至圣之功。此一句释经之“利贞”。</p><h2 id="《象》曰-山下出泉-蒙。-​" tabindex="-1">《象》曰：山下出泉，蒙。 ​ <a class="header-anchor" href="#《象》曰-山下出泉-蒙。-​" aria-label="Permalink to “《象》曰：山下出泉，蒙。 ​”">​</a></h2><p>王弼：山下出泉，未知所適，蒙之象也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：山下出泉，未有所適之处，是险而止，故蒙昧之象也。</p><h3 id="君子以果行育德。-​" tabindex="-1">君子以果行育德。 ​ <a class="header-anchor" href="#君子以果行育德。-​" aria-label="Permalink to “君子以果行育德。 ​”">​</a></h3><p>王弼：“果行”者，初筮之义也。“育德”者，养正之功也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：君子当发此蒙道，以果决其行，告示蒙者，则“初筮之义”。“育德”谓隐默怀藏，不自彰显，以育养其德。“果行”、“育德”者，自相违错，若童蒙来问，则果行也，寻常处众则育德，是不相须也。</p><h2 id="初六-发蒙-利用刑人-用说桎梏-以往吝。-​" tabindex="-1">初六：发蒙，利用刑人，用说桎梏，以往吝。 ​ <a class="header-anchor" href="#初六-发蒙-利用刑人-用说桎梏-以往吝。-​" aria-label="Permalink to “初六：发蒙，利用刑人，用说桎梏，以往吝。 ​”">​</a></h2><p>王弼：处蒙之初，二照其上，故蒙发也。蒙发疑明，刑说当也。“以往吝”，刑不可长。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“初六”至“以往吝”。正义曰：“发蒙”者，以初近於九二，二以阳处中，而明能照闇，故初六以能发去其蒙也。“利用刑人，用说桎梏”者，蒙既发去，无所疑滞，故利用刑戮于人，又利用说去罪人桎梏，以蒙既发去，疑事显明，刑人说桎梏皆得当。在足曰桎，在手曰梏。《小雅》云：“杻谓之梏，械谓之桎。”“以往吝”者，若以正道而往，即其事益善矣；若以刑人之道出往，往之即有鄙吝。</p><h3 id="《象》曰-利用刑人-以正法也。-​" tabindex="-1">《象》曰：“利用刑人‘，以正法也。 ​ <a class="header-anchor" href="#《象》曰-利用刑人-以正法也。-​" aria-label="Permalink to “《象》曰：“利用刑人‘，以正法也。 ​”">​</a></h3><p>王弼：刑人之道，道所恶也。以正法制，故刑人也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：且刑人之道乃贼害於物，是道之所恶，以利用刑人者，以正其法制，不可不刑矣。故刑罚不可不施於国，鞭扑不可不施於家。案：此经刑人、说人二事，《象》直云“利用刑人”一者，但举刑重故也。</p><h2 id="九二-包蒙吉-纳妇吉-子克家。-​" tabindex="-1">九二：包蒙吉，纳妇吉，子克家。 ​ <a class="header-anchor" href="#九二-包蒙吉-纳妇吉-子克家。-​" aria-label="Permalink to “九二：包蒙吉，纳妇吉，子克家。 ​”">​</a></h2><p>王弼：以刚居中，童蒙所归，包而不距则远近咸至，故“包蒙吉”也。妇者，配巳而成德者也。体阳而能包蒙，以刚而能居中，以此纳配物莫不应，故“纳妇吉”也。处于卦内，以刚接柔，亲而得中，能幹其任，施之於子，克家之义。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“九二”至“子克家”。正义曰：“包”谓包含，九二以刚居中，童蒙悉来归己，九二能含容而不距，皆与之决疑，故得吉也。九二以刚居中，阴来应之。“妇”谓配也，故纳此匹配而得吉也。此爻在下体之中，能包蒙纳妇，任内理中，幹了其任，即是子孙能克荷家事，故云“子克家”也。○注“亲而得中”。○正义曰：“亲而得中”者，言九二居下卦之中央，上下俱阴，以己之两阳迎接上下二阴，阴阳相亲，故云“亲而得中”也。“能幹其任”者，既能包蒙，又能纳匹，是能幹其任。</p><h3 id="《象》曰-子克家-刚柔节也。-​" tabindex="-1">《象》曰：“子克家”，刚柔节也。 ​ <a class="header-anchor" href="#《象》曰-子克家-刚柔节也。-​" aria-label="Permalink to “《象》曰：“子克家”，刚柔节也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以阳居於卦内，接待群阴，是刚柔相接，故克幹家事也。</p><h2 id="六三-勿用取女。见金夫-不有躬-无攸利。-​" tabindex="-1">六三：勿用取女。见金夫，不有躬，无攸利。 ​ <a class="header-anchor" href="#六三-勿用取女。见金夫-不有躬-无攸利。-​" aria-label="Permalink to “六三：勿用取女。见金夫，不有躬，无攸利。 ​”">​</a></h2><p>王弼：童蒙之时，阴求於阳，晦求於明，各求发其昧者也。六三在下卦之上，上九在上卦之上，男女之义也。上不求三而三求上，女先求男者也。女之为体，正行以待命者也。见刚夫而求之，故曰“不有躬”也。施之於女行在不顺故“勿用取女”，而“无攸利”。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>“六三”至“无攸利”。○正义曰：“勿用取女”者，女谓六三，言勿用取此六三之女。所以不须者，此童蒙之世，阴求於阳，是女求男之时也。“见金夫”者，谓上九以其刚阳，故称“金夫”。此六三之女，自往求见“金夫”。女之为礼，正行以待命而嫁。今先求於夫，是为女不能自保其躬，固守贞信，乃非礼而动，行既不顺，若欲取之，无所利益，故云“不有躬，无攸利”也。</p><h3 id="《象》曰-勿用取女-行不顺也。-​" tabindex="-1">《象》曰：“勿用取女”，行不顺也。 ​ <a class="header-anchor" href="#《象》曰-勿用取女-行不顺也。-​" aria-label="Permalink to “《象》曰：“勿用取女”，行不顺也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“勿用取女”之义。所以勿用取此女者，以女行不顺故也。</p><h2 id="六四-困蒙-吝。-​" tabindex="-1">六四：困蒙，吝。 ​ <a class="header-anchor" href="#六四-困蒙-吝。-​" aria-label="Permalink to “六四：困蒙，吝。 ​”">​</a></h2><p>王弼：独远於阳，处两阴之中，闇莫之发，故曰“困蒙”也。困於蒙昧，不能比贤以发其志，亦以鄙矣，故曰“吝”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此释六四爻辞也。六四在两阴之中，去九二既远，无人发去其童蒙，故曰困于蒙昧而有鄙吝。</p><h3 id="《象》曰-困蒙-之吝-独远实也。-​" tabindex="-1">《象》曰：“困蒙”之吝，独远实也。 ​ <a class="header-anchor" href="#《象》曰-困蒙-之吝-独远实也。-​" aria-label="Permalink to “《象》曰：“困蒙”之吝，独远实也。 ​”">​</a></h3><p>王弼：阳称实也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“独远实也”。○正义曰：“独远实’者，实谓九二之阳也。九二以阳，故称实也。六三近九二，六五近上九，又应九二，唯此六四既不近二，又不近上，故云“独远实也”。○注“阳实也”。○正义曰：阳主生息，故称实。阴主消损，故不得言实。</p><h2 id="六五-童蒙吉。-​" tabindex="-1">六五：童蒙吉。 ​ <a class="header-anchor" href="#六五-童蒙吉。-​" aria-label="Permalink to “六五：童蒙吉。 ​”">​</a></h2><p>王弼：以夫阴质居於尊位，不自任察而委於二，付物以能，不劳聪明，功斯克矣，故曰“童蒙吉”。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：言六五以阴居於尊位，其应在二，二刚而得中，五则以事委任於二，不劳巳之聪明，犹若童稚蒙昧之人，故所以得吉也。</p><h3 id="《象》曰-童蒙-之吉-顺以巽也。-​" tabindex="-1">《象》曰：“童蒙”之吉，顺以巽也。 ​ <a class="header-anchor" href="#《象》曰-童蒙-之吉-顺以巽也。-​" aria-label="Permalink to “《象》曰：“童蒙”之吉，顺以巽也。 ​”">​</a></h3><p>王弼：委物以能，不先不为，“顺以巽也”。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“顺以巽也”。正义曰：“顺以巽也”，释童蒙之吉，巽以顺也，犹委物於二。顺谓心顺，巽谓貌顺。故褚氏云：“顺者，心不违也。巽者，外迹相卑下也。”○注“委物以能”至“顺以巽也”。○正义曰：“委物以能”，谓委付事物与有能之人，谓委二也。“不先不为”者，五虽居尊位，而专委任於二，不在二先而首唱，是顺於二也。“不为”者，谓不自造为，是委任二也。不先於二，是心顺也；不自造为，是貌顺也。</p><h2 id="上九-击蒙-不利为寇-利御寇。-​" tabindex="-1">上九：击蒙，不利为寇，利御寇。 ​ <a class="header-anchor" href="#上九-击蒙-不利为寇-利御寇。-​" aria-label="Permalink to “上九：击蒙，不利为寇，利御寇。 ​”">​</a></h2><p>王弼：处蒙之终，以刚居上，能击去童蒙，以发其昧者也，故曰“击蒙”也。童蒙原发而已能击去之，合上下之愿，故莫不顺也。为之捍御，则物咸附之。若欲取之，则物咸叛矣，故“不利为寇，利御寇”也。</p><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：处蒙之终，以刚居上，能击去众阴之蒙，合上下之愿，故莫不顺从也。若因物之来即欲取之而为寇害，物皆叛矣，故“不利为寇”也。若物从外来，为之捍御，则物咸附之，故“利用御寇”也。</p><h3 id="《象》曰-利用御寇-上下顺也。-​" tabindex="-1">《象》曰：利用御寇，上下顺也。 ​ <a class="header-anchor" href="#《象》曰-利用御寇-上下顺也。-​" aria-label="Permalink to “《象》曰：利用御寇，上下顺也。 ​”">​</a></h3><h3 id="疏-19" tabindex="-1">疏 <a class="header-anchor" href="#疏-19" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：所宜利为物御寇者，由上下顺从故也。言此爻既能发去众蒙，以合上下之愿，又能为之御寇，故上下弥更顺从也。</p>',82)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
